class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)
        maxleft = {}
        i = 0

        while i < n:
            key = nums[i] - i
            if key in maxleft:
                maxleft[key] = max(maxleft[key], maxleft[key] + nums[i], nums[i])
            else:
                previdx = bisect.bisect_left(list(maxleft.keys()), key)
                if previdx == 0:
                    maxleft[key] = nums[i]
                else:
