                    prev_key, prev_val = None, None
                    for j in range(previdx):
                        k, v = list(maxleft.items())[j]
                        if k < key:
                            prev_key, prev_val = k, v
                    if prev_key is not None:
                        maxleft[key] = max(prev_val + nums[i], nums[i])
                    else:
                        maxleft[key] = nums[i]

                nextidx = bisect.bisect_right(list(maxleft.keys()), key)
                if nextidx < len(maxleft.keys()):
                    next_key, next_val = list(maxleft.items())[nextidx]
                    if next_val <= maxleft[key]:
                        del maxleft[next_key]

            i += 1

        return max(maxleft.values()) if maxleft else 0

